import React from 'react';
import { Package, Box, Truck } from 'lucide-react';

const KPIHeader = ({ orders }) => {
  const totalBranches = orders.length;
  const totalCbm = orders.reduce((sum, order) => sum + order.totalCbm, 0).toFixed(2);

  const totalTrucks = orders.reduce((totals, order) => {
    totals.jumbo4m += order.recommendedTrucks.jumbo4m || 0;
    totals.jumbo += order.recommendedTrucks.jumbo || 0;
    totals.dabbaba += order.recommendedTrucks.dabbaba || 0;
    return totals;
  }, { jumbo4m: 0, jumbo: 0, dabbaba: 0 });

  const kpis = [
    {
      title: 'إجمالي الفروع',
      value: totalBranches,
      icon: <Package className="w-6 h-6 text-blue-500" />,
      bgColor: 'bg-blue-50',
      borderColor: 'border-blue-100',
    },
    {
      title: 'إجمالي الحجم (CBM)',
      value: totalCbm,
      icon: <Box className="w-6 h-6 text-purple-500" />,
      bgColor: 'bg-purple-50',
      borderColor: 'border-purple-100',
    },
    {
      title: 'السيارات المقترحة',
      value: (
        <div className="flex gap-2 text-sm mt-1">
          <span className="bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded">جامبو 4م: {totalTrucks.jumbo4m}</span>
          <span className="bg-pink-100 text-pink-700 px-2 py-0.5 rounded">جامبو: {totalTrucks.jumbo}</span>
          <span className="bg-orange-100 text-orange-700 px-2 py-0.5 rounded">دبابة: {totalTrucks.dabbaba}</span>
        </div>
      ),
      icon: <Truck className="w-6 h-6 text-indigo-500" />,
      bgColor: 'bg-indigo-50',
      borderColor: 'border-indigo-100',
      isComponent: true
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 h-full">
      {kpis.map((kpi, index) => (
        <div key={index} className={`rounded-2xl p-5 border shadow-sm flex items-start gap-4 ${kpi.bgColor} ${kpi.borderColor}`}>
          <div className="p-3 bg-white rounded-xl shadow-sm">
            {kpi.icon}
          </div>
          <div>
            <h3 className="text-slate-500 text-sm font-semibold">{kpi.title}</h3>
            {kpi.isComponent ? (
              kpi.value
            ) : (
              <p className="text-2xl font-bold text-slate-800 mt-1">{kpi.value}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default KPIHeader;
